115	// matching types.AgentName values). Agents not listed here still work via
116	// the picker — users just see an empty list and should edit settings.json
117	// manually to add skills.
118	var curatedReviewSkills = map[string][]curatedSkill{
119		"claude-code": {
120			{Name: "/pr-review-toolkit:review-pr", Desc: "Full PR review"},
121			{Name: "/pr-review-toolkit:code-reviewer", Desc: "Code review for standards"},
122			{Name: "/test-auditor", Desc: "Test coverage audit"},
123			{Name: "/verification-before-completion", Desc: "Verify before marking done"},
124			{Name: "/requesting-code-review", Desc: "Prepare code for review"},
