207	func newReviewCmd() *cobra.Command {
208		var edit bool
209		var trackOnly bool
210	
211		cmd := &cobra.Command{
212			Use:   "review",
213			Short: "Run configured review skills against the current branch",
214			Long: `Run the review skills configured in .entire/settings.json against
