233	func runReview(ctx context.Context, cmd *cobra.Command, trackOnly bool) error {
234		out := cmd.OutOrStdout()
235	
236		// 1. Pre-flight: must be in a git repo.
237		if _, err := paths.WorktreeRoot(ctx); err != nil {
238			cmd.SilenceUsage = true
239			fmt.Fprintln(cmd.ErrOrStderr(), "Not a git repository. Run `entire enable` first.")
240			return NewSilentError(errors.New("not a git repository"))
241		}
242	
243		// 2. Load config; trigger first-run picker if missing.
244		s, err := settings.Load(ctx)
245		if err != nil || s == nil || len(s.Review) == 0 {
246			picked, pickErr := runReviewConfigPicker(ctx, out)
247			if pickErr != nil {
248				return pickErr
249			}
250			s = &settings.EntireSettings{Review: picked}
251		}
252	
253		// 3. Pick agent.
254		agentName, skills, err := selectReviewAgent(s.Review)
255		if err != nil {
256			return err
257		}
258	
259		// 4. Re-run guard: check if HEAD's checkpoint already has a review.
260		if reviewed, meta := headHasReviewCheckpoint(ctx); reviewed {
261			var proceed bool
262			form := NewAccessibleForm(huh.NewGroup(
263				huh.NewConfirm().
264					Title(fmt.Sprintf("Already reviewed: %s. Proceed anyway?", meta)).
265					Value(&proceed),
266			))
267			if err := form.Run(); err != nil {
268				fmt.Fprintln(out, "prompt cancelled")
269				return err //nolint:wrapcheck // propagate huh cancellation
270			}
271			if !proceed {
272				fmt.Fprintln(out, "Review cancelled.")
273				return nil
274			}
275		}
276	
277		// 5. Resolve HEAD for the pending marker.
278		headSHA, err := currentHeadSHA(ctx)
279		if err != nil {
280			return fmt.Errorf("resolve HEAD: %w", err)
281		}
282	
283		// 6. Write pending marker (agent hook will adopt it).
284		if err := WritePendingReviewMarker(PendingReviewMarker{
285			AgentName:   agentName,
286			Skills:      skills,
287			StartingSHA: headSHA,
288			StartedAt:   time.Now().UTC(),
289		}); err != nil {
290			return fmt.Errorf("write pending marker: %w", err)
291		}
292	
293		if trackOnly {
294			fmt.Fprintln(out, "Pending review marker written.")
295			fmt.Fprintf(out, "Start %s and run these skills manually: %s\n", agentName, strings.Join(skills, ", "))
296			return nil
297		}
298	
299		// 7. Spawn agent with the composed initial prompt.
300		launcher, ok := agent.LauncherFor(types.AgentName(agentName))
301		if !ok {
302			fmt.Fprintf(out, "%s does not support subprocess launch yet. Falling back to --track-only.\n", agentName)
303			fmt.Fprintf(out, "Start %s manually and run: %s\n", agentName, strings.Join(skills, ", "))
304			return nil
305		}
306		prompt := composeReviewPrompt(skills)
307		execCmd, err := launcher.LaunchCmd(ctx, prompt)
308		if err != nil {
309			return fmt.Errorf("launch %s: %w", agentName, err)
310		}
311		if err := execCmd.Run(); err != nil {
312			// Best-effort cleanup: clear the pending marker so a stale marker
313			// doesn't tag the next non-review session.
314			_ = ClearPendingReviewMarker() //nolint:errcheck // best-effort cleanup
315			return fmt.Errorf("agent exited: %w", err)
316		}
317		return nil
318	}
