320	// selectReviewAgent picks an agent from the configured review map. v1: single
321	// agent. If multiple are configured, returns the one that sorts first by name
322	// (deterministic default). Returns an error if the map is empty.
323	func selectReviewAgent(review map[string][]string) (string, []string, error) {
324		if len(review) == 0 {
325			return "", nil, errors.New("no review skills configured")
326		}
327		// Deterministic pick: alphabetical by agent name.
328		var names []string
329		for name, skills := range review {
330			if len(skills) > 0 {
331				names = append(names, name)
332			}
333		}
334		if len(names) == 0 {
335			return "", nil, errors.New("no review skills configured")
336		}
337		sort.Strings(names)
338		pick := names[0]
339		return pick, review[pick], nil
340	}
341	
342	// composeReviewPrompt builds the initial prompt the agent receives.
343	func composeReviewPrompt(skills []string) string {
344		var sb strings.Builder
345		sb.WriteString("Please run these review skills in order:\n")
346		for i, skill := range skills {
347			fmt.Fprintf(&sb, "  %d. %s\n", i+1, skill)
348		}
349		return sb.String()
350	}
351	
352	// currentHeadSHA returns the current HEAD commit hash as a 40-char hex string.
353	func currentHeadSHA(ctx context.Context) (string, error) {
354		repoRoot, err := paths.WorktreeRoot(ctx)
355		if err != nil {
356			return "", fmt.Errorf("locate repo root: %w", err)
357		}
358		execCmd := exec.CommandContext(ctx, "git", "-C", repoRoot, "rev-parse", "HEAD")
359		output, err := execCmd.Output()
360		if err != nil {
361			return "", fmt.Errorf("git rev-parse HEAD: %w", err)
362		}
363		return strings.TrimSpace(string(output)), nil
364	}
365	
366	// headHasReviewCheckpoint checks whether HEAD's checkpoint metadata includes
367	// a review session. Returns (true, infoString) if HasReview is set.
368	// This is O(1): read the Entire-Checkpoint trailer from HEAD, then read the
369	// CheckpointSummary from entire/checkpoints/v1.
370	func headHasReviewCheckpoint(ctx context.Context) (bool, string) {
371		repoRoot, err := paths.WorktreeRoot(ctx)
372		if err != nil {
373			return false, ""
374		}
375		// Read HEAD commit message to extract checkpoint trailer.
376		execCmd := exec.CommandContext(ctx, "git", "-C", repoRoot, "log", "-1", "--format=%B")
377		output, err := execCmd.Output()
378		if err != nil {
379			return false, ""
380		}
381		cpID, ok := trailers.ParseCheckpoint(string(output))
382		if !ok {
383			return false, ""
384		}
385		repo, err := git.PlainOpen(repoRoot)
386		if err != nil {
387			return false, ""
388		}
389		store := checkpoint.NewGitStore(repo)
390		summary, err := store.ReadCommitted(ctx, cpID)
391		if err != nil || summary == nil {
392			return false, ""
393		}
394		if !summary.HasReview {
395			return false, ""
396		}
397		// Build a short description for the re-run prompt.
398		return true, fmt.Sprintf("checkpoint %s", cpID)
399	}
400	
401	// saveReviewConfig persists the review map into .entire/settings.json while
402	// preserving all other settings.
403	func saveReviewConfig(ctx context.Context, review map[string][]string) error {
404		s, err := settings.Load(ctx)
405		if err != nil || s == nil {
406			s = &settings.EntireSettings{}
407		}
408		s.Review = review
409		if err := settings.Save(ctx, s); err != nil {
410			return fmt.Errorf("save settings: %w", err)
411		}
412		return nil
413	}
