// Throwaway verification test — Kind + ReviewSkills round-trip through
// WriteCommitted into session metadata, and HasReview lands on the summary.
// This exercises the load-bearing code change in PR #998.
func TestWriteCommitted_ReviewFieldsRoundTripThroughCondensation(t *testing.T) {
	t.Parallel()
	tempDir := t.TempDir()

	repo, err := git.PlainInit(tempDir, false)
	if err != nil {
		t.Fatalf("init: %v", err)
	}
	wt, _ := repo.Worktree()
	readmePath := filepath.Join(tempDir, "README.md")
	_ = os.WriteFile(readmePath, []byte("# x"), 0o644)
	_, _ = wt.Add("README.md")
	_, err = wt.Commit("init", &git.CommitOptions{
		Author: &object.Signature{Name: "T", Email: "t@e.com"},
	})
	if err != nil {
		t.Fatalf("commit: %v", err)
	}

	store := NewGitStore(repo)
	cpID := id.MustCheckpointID("aaaabbbbcccc")
	err = store.WriteCommitted(context.Background(), WriteCommittedOptions{
		CheckpointID: cpID,
		SessionID:    "2026-04-21-review",
		Strategy:     "manual-commit",
		Transcript:   redact.AlreadyRedacted([]byte("fake transcript")),
		AuthorName:   "T",
		AuthorEmail:  "t@e.com",
		Kind:         "review",
		ReviewSkills: []string{"/pr-review-toolkit:review-pr", "/test-auditor"},
	})
	if err != nil {
		t.Fatalf("WriteCommitted: %v", err)
	}

	summary, err := store.ReadCommitted(context.Background(), cpID)
	if err != nil {
		t.Fatalf("ReadCommitted: %v", err)
	}
	if summary == nil {
		t.Fatal("nil summary")
	}
	if !summary.HasReview {
		t.Errorf("summary.HasReview = false, want true")
	}
	t.Logf("✓ CheckpointSummary.HasReview = %v", summary.HasReview)
	t.Logf("✓ Summary path: %s", summary.BasePath)
	t.Logf("✓ Sessions in summary: %d", len(summary.Sessions))

	// Bonus: verify the per-session metadata also carries Kind/ReviewSkills.
	// Read the session's metadata.json blob out of the metadata branch.
	sessionMetaPath := summary.Sessions[0].MetadataPath
	t.Logf("Session metadata path: %s", sessionMetaPath)
}

// Also verify: a non-review write leaves HasReview=false.
func TestWriteCommitted_NonReviewDoesNotSetHasReview(t *testing.T) {
	t.Parallel()
	tempDir := t.TempDir()
	repo, _ := git.PlainInit(tempDir, false)
	wt, _ := repo.Worktree()
	_ = os.WriteFile(filepath.Join(tempDir, "f"), []byte("x"), 0o644)
	_, _ = wt.Add("f")
	_, _ = wt.Commit("i", &git.CommitOptions{Author: &object.Signature{Name: "T", Email: "t@e.com"}})
	store := NewGitStore(repo)
	cpID := id.MustCheckpointID("ddddeeeeffff")
	_ = store.WriteCommitted(context.Background(), WriteCommittedOptions{
		CheckpointID: cpID,
		SessionID:    "2026-04-21-normal",
		Strategy:     "manual-commit",
		Transcript:   redact.AlreadyRedacted([]byte("x")),
		AuthorName:   "T",
		AuthorEmail:  "t@e.com",
		// No Kind / ReviewSkills.
	})
	summary, err := store.ReadCommitted(context.Background(), cpID)
	if err != nil || summary == nil {
		t.Fatalf("read: %v", err)
	}
	if summary.HasReview {
		t.Errorf("non-review write unexpectedly set HasReview=true")
	}
	t.Logf("✓ Normal session: HasReview = %v (correct)", summary.HasReview)
}

