// runReviewConfigPicker presents a huh multi-select for each installed agent
// that has curated review skills, and saves the selection to
// .entire/settings.json. Previously-saved skills are pre-checked so users
// can confirm/adjust without re-entering from scratch.
func runReviewConfigPicker(ctx context.Context, out io.Writer) (map[string][]string, error) {
	installed := GetAgentsWithHooksInstalled(ctx)
	if len(installed) == 0 {
		return nil, errors.New("no agents installed; run 'entire enable' first")
	}

	// Narrow to agents that have a curated skills list — others need manual
	// editing of settings.json and aren't meaningful in the picker.
	var configurable []types.AgentName
	for _, name := range installed {
		if curated, ok := curatedReviewSkills[string(name)]; ok && len(curated) > 0 {
			configurable = append(configurable, name)
		}
	}
	if len(configurable) == 0 {
		return nil, errors.New("no installed agents have curated review skills; edit .entire/settings.json directly")
	}

	// Load existing config so we can pre-check already-saved skills.
	existing := map[string][]string{}
	if s, err := settings.Load(ctx); err == nil && s != nil {
		existing = s.Review
	}

	// Up-front header so the user knows how many agents they'll step through
	// and in what order.
	agentList := make([]string, 0, len(configurable))
	for _, n := range configurable {
		agentList = append(agentList, string(n))
	}
	fmt.Fprintf(out, "Configuring review skills for %d agent(s): %s\n", len(configurable), strings.Join(agentList, ", "))
	fmt.Fprintln(out, "(Previously-saved skills are pre-checked. Use space to toggle, enter to confirm.)")
	fmt.Fprintln(out)

	selected := map[string][]string{}
	for i, agentName := range configurable {
		curated := curatedReviewSkills[string(agentName)]
		alreadyPicked := map[string]bool{}
		for _, s := range existing[string(agentName)] {
			alreadyPicked[s] = true
		}

		// Seed the bound slice with existing picks so huh honors pre-selection
		// even in accessible mode, where Option.Selected(true) is not always
		// surfaced identically to TUI mode.
		var picks []string
		for _, s := range curated {
			if alreadyPicked[s.Name] {
				picks = append(picks, s.Name)
			}
		}

		options := make([]huh.Option[string], 0, len(curated))
		for _, s := range curated {
			opt := huh.NewOption(fmt.Sprintf("%s — %s", s.Name, s.Desc), s.Name)
			if alreadyPicked[s.Name] {
				opt = opt.Selected(true)
			}
			options = append(options, opt)
		}

		title := fmt.Sprintf("[%d/%d] Review skills for %s", i+1, len(configurable), agentName)
		form := NewAccessibleForm(huh.NewGroup(
			huh.NewMultiSelect[string]().
				Title(title).
				Description(fmt.Sprintf("Agent: %s", agentName)).
				Options(options...).
				Value(&picks),
		))
		if err := form.Run(); err != nil {
			return nil, fmt.Errorf("picker for %s: %w", agentName, err)
		}
		if len(picks) > 0 {
			selected[string(agentName)] = picks
		}
	}
	if len(selected) == 0 {
		return nil, errors.New("no review skills selected")
	}
	if err := saveReviewConfig(ctx, selected); err != nil {
		return nil, err
	}
	fmt.Fprintln(out, "Saved review config to .entire/settings.json. Edit directly or run `entire review --edit`.")
	return selected, nil
}

